Use ASP.NET Core's **`WebApplicationFactory<T>`** — it hosts your app in-process with a test HTTP client, so you get real HTTP round-trips with zero network overhead.

### Setup

```bash
dotnet add package Microsoft.AspNetCore.Mvc.Testing
dotnet add package ModelContextProtocol --prerelease   # official C# MCP SDK
```

### Test class

```csharp
using Microsoft.AspNetCore.Mvc.Testing;
using ModelContextProtocol.Client;
using ModelContextProtocol.Protocol;

public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
        => _factory = factory;

    private async Task<IMcpClient> CreateMcpClientAsync()
    {
        var httpClient = _factory.CreateClient();

        // SseClientTransport points at the in-memory test server
        var transport = new SseClientTransport(
            new SseClientTransportOptions
            {
                Endpoint = new Uri(httpClient.BaseAddress!, "/sse"),
                // or "/mcp" — whatever your server's SSE endpoint is
            },
            httpClient);          // pass the test HttpClient

        return await McpClientFactory.CreateAsync(transport);
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        await using var client = await CreateMcpClientAsync();

        var capabilities = client.ServerCapabilities;

        Assert.NotNull(capabilities);
        Assert.NotNull(capabilities.Tools);
    }

    [Fact]
    public async Task ListTools_ReturnsExpectedTool()
    {
        await using var client = await CreateMcpClientAsync();

        var tools = await client.ListToolsAsync();

        Assert.Contains(tools, t => t.Name == "my-tool");
    }

    [Fact]
    public async Task CallTool_ReturnsResult()
    {
        await using var client = await CreateMcpClientAsync();

        var result = await client.CallToolAsync(
            "my-tool",
            new Dictionary<string, object?> { ["input"] = "hello" });

        Assert.False(result.IsError);
        var text = result.Content
            .OfType<TextContent>()
            .First();
        Assert.Contains("expected output", text.Text);
    }
}
```

### Key points

- **`WebApplicationFactory`** boots your real `Program`/`Startup` in-memory — middleware, DI, routing all run normally.
- Pass `_factory.CreateClient()` into `SseClientTransport` so all HTTP goes through the in-process test server.
- The official `ModelContextProtocol` NuGet SDK handles the SSE/JSON-RPC framing for you.
- **No ports, no processes** — tests are fast and CI-friendly.
- If you use the newer **Streamable HTTP** transport (`/mcp` endpoint), swap `SseClientTransport` for `StreamableHttpClientTransport` with the same pattern.

### Overriding services for testing

```csharp
var factory = _factory.WithWebHostBuilder(builder =>
{
    builder.ConfigureServices(services =>
    {
        // Replace a real dependency with a fake
        services.AddSingleton<IMyService, FakeMyService>();
    });
});
var httpClient = factory.CreateClient();
```

This gives you full protocol-level integration tests (initialize → list → call → assert) entirely in-process.
